import fs from'node:fs';import crypto from'node:crypto';import{createCommon}from'../create-common.mjs';import{defaultState}from'../src/State.mjs';
const m=createCommon(),rows=[],dir=new URL('../research/common-cases/',import.meta.url);fs.mkdirSync(dir,{recursive:true});function add(name,state){const v=m.compute(state).slice();fs.writeFileSync(new URL(name+'.f32',dir),new Uint8Array(v.buffer));rows.push({name,state,sha256:crypto.createHash('sha256').update(v).digest('hex')});}add('neutral',defaultState());for(const[group,n,value]of[['rotation',12,.25],['translation',3,.006]])for(let i=0;i<n;i++){const s=defaultState();s.gnm[group][i]=value;add(group+'-'+i,s);}const s=defaultState();s.anny.phenotypes.weight=.8;s.anny.pose.spine02=[10,-12,8];s.anny.pose['upperarm01.L']=[15,25,-20];s.gnm.rotation[0]=.15;s.gnm.rotation[4]=.2;s.gnm.rotation[7]=.1;s.gnm.expression[200]=1;s.gnm.identity[0]=.4;add('combined',s);fs.writeFileSync(new URL('manifest.json',dir),JSON.stringify({fingerprint:m.adapterFingerprint,topology:m.canonical.topologySha256,cases:rows},null,2));console.log({commonCases:rows.length,signature:m.adapterFingerprint});
